            yield return option;

        yield return new NarrativeOption("reachman_childhood_tourney_games_option", new TextObject("{=bab_reachman_childhood_tourney_games_title}played at tourneys and knighthood."), new TextObject("{=bab_reachman_childhood_tourney_games_desc}You and the other children made wicker shields, chose queens of love and beauty, and reenacted famous tilts until every hedge became a list."), (args, u) => u.UpgradeRidingPolearmSkills(args, DefaultCharacterAttributes.Endurance), ccm => IsReachman(ccm), ccm => NarrativeEquipmentHelper.SetPlayerCharacterAnimation(ccm, "player_childhood_character", "act_childhood_apprentice"));
    }

