        yield return new NarrativeOption("reachman_adulthood_campaign_option", new TextObject("{=bab_reachman_adulthood_campaign_title}you distinguished yourself during a local campaign."), new TextObject("{=bab_reachman_adulthood_campaign_desc}When banners were called in the Reach, you marched with the host and kept your courage when scouting, skirmishing, and hard close fighting replaced youthful drills."), (args, u) => { u.UpgradeLeadershipTacticsSkills(args, DefaultCharacterAttributes.Cunning); args.SetRenownToAdd(15); }, ccm => IsReachman(ccm) && (!CharacterObject.PlayerCharacter.IsFemale && NarrativeChoiceState.YouthWas("reachman_youth_levy_option", "reachman_youth_scout_option")), ccm => NarrativeEquipmentHelper.SetPlayerCharacterAnimation(ccm, "player_adulthood_character", "act_drafted_to_war_pose"));
        yield return new NarrativeOption("reachman_adulthood_court_service_option", new TextObject("{=bab_reachman_adulthood_court_service_title}you won influence in a great household."), new TextObject("{=bab_reachman_adulthood_court_service_desc}Your judgment, discretion, and command of household politics earned you trust in the flowered courts and tourney grounds of the Reach, and people began seeking your help before presenting delicate requests."), (args, u) => { u.UpgradeStewardCharmSkills(args, DefaultCharacterAttributes.Social); args.SetRenownToAdd(10); }, ccm => IsReachman(ccm) && (NarrativeChoiceState.YouthWas("reachman_youth_courtier_option")), ccm => NarrativeEquipmentHelper.SetPlayerCharacterAnimation(ccm, "player_adulthood_character", "act_childhood_manners"));
